import { describe, expect, it } from 'vitest'

import {
  buildDepositForTokenPlan,
  buildListAboveFloorPlan,
  buildSwapNftsPlan,
} from '../../src/encoders/marketPlans'
import { planStepToCall } from '../../src/execution/encodeCalls'
import type { PlanStep } from '../../src/plan/types'

const ctx = { chainId: 1 } as const
const COLLECTION = '0xAAaA000000000000000000000000000000000001'
const COLLECTION_TOKEN = '0xCCCC000000000000000000000000000000000001'
const RECIPIENT = '0x1111111111111111111111111111111111111111'

function action(steps: PlanStep[], id: string): PlanStep {
  const step = steps.find((candidate) => candidate.id === id)
  if (!step) throw new Error(`Missing step ${id}.`)
  return step
}

const calldata = (step: PlanStep) => planStepToCall(step).data

describe('golden: frontend-parity market plan calldata', () => {
  it('Locker.deposit', () => {
    const steps = buildDepositForTokenPlan(ctx, {
      collection: COLLECTION,
      tokenIds: [200n, 201n],
      recipient: RECIPIENT,
      isApprovedForAll: false,
    })
    expect(calldata(action(steps, 'deposit'))).toMatchInlineSnapshot(`""`)
  })

  it('Locker.redeem', () => {
    const steps = buildSwapNftsPlan(ctx, {
      account: RECIPIENT,
      collection: COLLECTION,
      tokenIds: [2140n, 2141n],
      depositTokenIds: [900n],
      collectionToken: COLLECTION_TOKEN,
      recipient: RECIPIENT,
      isApprovedForAll: false,
    })
    expect(calldata(action(steps, 'redeem'))).toMatchInlineSnapshot(`""`)
  })

  it('Locker.swapBatch', () => {
    const steps = buildSwapNftsPlan(ctx, {
      account: RECIPIENT,
      collection: COLLECTION,
      tokenIds: [2140n, 2141n],
      depositTokenIds: [900n, 901n],
      recipient: RECIPIENT,
      isApprovedForAll: false,
    })
    expect(calldata(action(steps, 'swap'))).toMatchInlineSnapshot(`""`)
  })

  it('Listings.fillListings with owner-safe groups', () => {
    const steps = buildSwapNftsPlan(ctx, {
      account: RECIPIENT,
      collection: COLLECTION,
      tokenIds: [],
      listedItems: [
        { tokenId: 2140n, floorMultiple: 126 },
        { tokenId: 2142n, floorMultiple: 140 },
      ],
      depositTokenIds: [900n],
      collectionToken: COLLECTION_TOKEN,
      recipient: RECIPIENT,
      isApprovedForAll: false,
    })
    expect(calldata(action(steps, 'fill'))).toMatchInlineSnapshot(`""`)
  })

  it('Listings.createListings with per-item terms', () => {
    const steps = buildListAboveFloorPlan(ctx, {
      account: RECIPIENT,
      owner: RECIPIENT,
      collection: COLLECTION,
      items: [
        { tokenId: 200n, floorMultiple: 110 },
        { tokenId: 201n, floorMultiple: 150 },
      ],
      duration: 604_800,
      created: 1_750_000_000,
      isApprovedForAll: false,
    })
    expect(calldata(action(steps, 'list'))).toMatchInlineSnapshot(`""`)
  })
})
